import * as T from '../vendor/three.module.js';
import {createChibi} from './model.js';
import {createLightingBank,KEY} from './lighting.js';
const $=id=>document.getElementById(id),stage=$('stage'),renderer=new T.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor('#e8e1d1');stage.append(renderer.domElement);
const query=new URLSearchParams(location.search),modelOptions={geometryDetail:query.get('detail')==='economical'?'economical':'smooth',batchStaticInk:query.get('batch')!=='off',batchFaceInk:query.get('faceBatch')==='on',irisWidth:query.get('eyes')==='bold'?.065:.048,irisAsymmetry:query.get('eyes')==='asymmetric'?'reference':'current',neutralEyeContour:query.get('lids')==='narrow'?'narrow':'current',hairContour:query.get('hair')==='angular'?'angular':'rounded',gaitContact:query.get('gait')==='legacy'?'legacy':'grounded',bodyOutline:query.get('bodyInk')==='defined'?'defined':'current',gestureReach:query.get('gesture')==='forward'?'forward':'current',tuftVolume:query.get('tuft')==='rounded'?'rounded':'current',tuftAttachment:query.get('tuftRoot')==='floating'?'floating':'attached'};
const comparison=document.getElementById('modelStudy');for(const name of ['hair','detail','eyes','lids','gait']){const input=comparison.elements.namedItem(name),value=query.get(name);if([...input.options].some(o=>o.value===value))input.value=value;}comparison.onsubmit=e=>{e.preventDefault();const next=new URL(location.href);for(const name of ['hair','detail','eyes','lids','gait'])next.searchParams.set(name,comparison.elements.namedItem(name).value);location.assign(next.href);};
const scene=new T.Scene(),model=createChibi(modelOptions);scene.add(model.root);const floor=new T.Mesh(new T.PlaneGeometry(20,20),new T.MeshBasicMaterial({color:'#d2c9b6'}));floor.rotation.x=-Math.PI/2;floor.position.y=-.015;scene.add(floor);
const grid=new T.GridHelper(12,24,'#b3aa98','#c6bca8');grid.position.y=-.01;scene.add(grid);
const ambient=new T.AmbientLight(0xffffff,.42),keyLight=new T.DirectionalLight(0xffffff,.8);keyLight.position.copy(KEY);scene.add(ambient,keyLight);
const sceneryBank=createLightingBank('scenery'),floorModes=sceneryBank.variants(floor.material);
const wall=new T.Mesh(new T.BoxGeometry(.8,1.5,.12),new T.MeshBasicMaterial({color:'#85898a'}));wall.position.set(-.27,.75,.65);wall.visible=false;scene.add(wall);
let camera,yaw=0,elevation=.09,raf,last=0,dead=false;const target=new T.Vector3(0,.94,0);
function resize(){const w=stage.clientWidth,h=stage.clientHeight;renderer.setSize(w,h,false);const a=w/h,focus=$('headFocus').checked,span=focus?Math.max(.86,.78/a):1.25;if($('camera').value==='perspective'){camera=new T.PerspectiveCamera(focus?2*Math.atan(span/5)*180/Math.PI:32,a,.05,60);}else camera=new T.OrthographicCamera(-span*a,span*a,span,-span,.05,60);positionCamera();}
function positionCamera(){const focus=$('headFocus').checked;target.set(0,focus?model.parameters.headY+.06:.94,0);camera.position.set(Math.sin(yaw)*5,target.y+(focus?0:.25)+elevation*5,Math.cos(yaw)*5);camera.lookAt(target);camera.updateMatrixWorld();}
function setYaw(deg){yaw=deg*Math.PI/180;$('yaw').value=deg;$('angle').value=Math.round(deg)+'°';positionCamera();}
const labels=['Front','Front left','Left','Back left','Back','Back right','Right','Front right'];labels.forEach((label,i)=>{let b=document.createElement('button');b.textContent=label;b.onclick=()=>{ $('orbit').checked=false;setYaw(i*45);};$('views').append(b);});
$('yaw').oninput=e=>setYaw(+e.target.value);$('camera').onchange=resize;$('pose').onchange=e=>model.setPose(e.target.value);$('expression').onchange=e=>model.setExpression(e.target.value);$('construction').onchange=e=>model.setConstruction(e.target.checked);$('outline').onchange=e=>model.setOutline(e.target.checked);$('wall').onchange=e=>wall.visible=e.target.checked;
$('headStudy').onchange=e=>model.setHeadStudy(e.target.checked);
$('headFocus').onchange=resize;
function reset(){model.reset();model.setExpression('neutral');setYaw(0);elevation=.09;$('pose').value='neutral';$('expression').value='neutral';$('orbit').checked=false;$('headFocus').checked=false;$('headStudy').checked=false;model.setHeadStudy(false);$('construction').checked=false;$('outline').checked=true;$('wall').checked=false;wall.visible=false;model.setConstruction(false);model.setOutline(true);resize();}
$('reset').onclick=reset;let drag;stage.onpointerdown=e=>{if(e.button!==0||drag)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY};stage.setPointerCapture(e.pointerId);$('orbit').checked=false;};stage.onpointermove=e=>{if(!drag||e.pointerId!==drag.id)return;setYaw((yaw*180/Math.PI+(e.clientX-drag.x)*.4+360)%360);elevation=Math.max(-.05,Math.min(.5,elevation+(e.clientY-drag.y)*.001));drag={id:e.pointerId,x:e.clientX,y:e.clientY};positionCamera();};function releaseDrag(e){if(!drag||(e&&e.pointerId!==drag.id))return;const id=drag.id;drag=null;if(stage.hasPointerCapture(id))stage.releasePointerCapture(id);}stage.onpointerup=stage.onpointercancel=stage.onlostpointercapture=releaseDrag;addEventListener('blur',()=>releaseDrag());document.addEventListener('visibilitychange',()=>{if(document.hidden)releaseDrag();});
$('lighting').onchange=e=>{model.setLighting(e.target.value);floor.material=floorModes[e.target.value];};
const observer=new ResizeObserver(resize);observer.observe(stage);resize();
function frame(now){if(dead)return;const dt=last?Math.min(.1,(now-last)/1000):0;last=now;if(!document.hidden){model.update(dt);if($('orbit').checked)setYaw((yaw*180/Math.PI+dt*24)%360);renderer.render(scene,camera);}raf=requestAnimationFrame(frame);}raf=requestAnimationFrame(frame);
const stats=model.stats();$('stats').textContent=`${Math.round(stats.triangles).toLocaleString()} model triangles including ink shells · ${stats.textureBytes} model texture bytes · local Three.js r128`;
// Offscreen renderers are short-lived; sample camera/scene always identical.
function reviewRender(height=160,angle=0,w=240,h=220,options={}){const r=new T.WebGLRenderer({antialias:true,preserveDrawingBuffer:true});r.setPixelRatio(1);r.setSize(w,h);r.setClearColor('#e8e1d1');const s=new T.Scene(),m=createChibi({...modelOptions,...options.parameters});s.add(m.root);m.root.visible=options.visible!==false;m.setPose(options.pose||'neutral');m.setExpression(options.expression||'neutral');m.setLighting(options.lighting||'flat');m.setHeadStudy(options.headStudy===true);const end=Number.isFinite(options.time)&&options.time>0?options.time:0;for(let elapsed=0;elapsed<end;){const dt=Math.min(.025,end-elapsed);m.update(dt);elapsed+=dt;}let f=new T.Mesh(new T.PlaneGeometry(12,12),new T.MeshBasicMaterial({color:'#d2c9b6'}));f.rotation.x=-Math.PI/2;f.position.y=-.015;s.add(f);const g=new T.GridHelper(8,16,'#b3aa98','#c6bca8');g.position.y=-.01;s.add(g);
 const c=new T.OrthographicCamera(-1.25*w/h,1.25*w/h,1.25,-1.25,.05,60);c.position.set(Math.sin(angle*Math.PI/180)*5,.94,Math.cos(angle*Math.PI/180)*5);c.lookAt(0,.94,0);m.root.scale.setScalar(height*2.5/(h*m.height));r.render(s,c);const out=document.createElement('canvas');out.width=w;out.height=h;out.getContext('2d').drawImage(r.domElement,0,0);const calls=r.info.render.calls;m.dispose();f.geometry.dispose();f.material.dispose();g.geometry.dispose();g.material.dispose();r.dispose();r.forceContextLoss();return {canvas:out,calls};}
for(const height of [32,64,96,160]){let fig=document.createElement('figure'),cap=document.createElement('figcaption');const out=reviewRender(height);cap.textContent=height+'px model height';fig.append(out.canvas,cap);$('samples').append(fig);}
const sheetStudyTag=[modelOptions.hairContour,modelOptions.geometryDetail,modelOptions.irisAsymmetry==='reference'?'asymmetric-irises':modelOptions.irisWidth===.065?'bold-eyes':'current-eyes',modelOptions.neutralEyeContour==='narrow'?'narrow-lids':'current-lids',modelOptions.gaitContact].join('-')+(modelOptions.bodyOutline==='defined'?'-defined-body-ink':'')+(modelOptions.gestureReach==='forward'?'-forward-gesture':'')+(modelOptions.tuftVolume==='rounded'?'-rounded-tuft':'')+(modelOptions.tuftAttachment==='floating'?'-floating-tuft':'')+(modelOptions.batchFaceInk?'-batched-face-ink':'');
function saveSheet(headStudy=false){const out=document.createElement('canvas');out.width=1200;out.height=520;let ctx=out.getContext('2d');ctx.fillStyle='#fffaf0';ctx.fillRect(0,0,1200,520);for(let i=0;i<8;i++){let r=reviewRender(185,i*45,290,230,{pose:document.getElementById('pose').value,expression:document.getElementById('expression').value,lighting:document.getElementById('lighting').value,headStudy});let x=(i%4)*300,y=Math.floor(i/4)*260;ctx.drawImage(r.canvas,x+5,y);ctx.fillStyle='#282c30';ctx.font='15px sans-serif';ctx.fillText(labels[i]+' · '+i*45+'°',x+15,y+248);}let a=$('download');a.href=out.toDataURL('image/png');a.download=(headStudy?'head-structure-':'sailor-')+sheetStudyTag+'-'+document.getElementById('pose').value+'-'+document.getElementById('expression').value+'-'+document.getElementById('lighting').value+'-phase0-eight-views.png';a.textContent=(headStudy?'Download head structure / ':'Download ')+document.getElementById('pose').value+' / '+document.getElementById('expression').value+' / '+document.getElementById('lighting').value+' sheet (starting pose) · '+sheetStudyTag.replaceAll('-',' ');a.hidden=false;};
$('capture').onclick=()=>saveSheet(false);$('captureHead').onclick=()=>saveSheet(true);
function saveMotionSheet(){
 const pose=$('pose').value,expression=$('expression').value,lighting=$('lighting').value;
 const period={idle:Math.PI,walk:2*Math.PI/7,wave:Math.PI/4}[pose]||0;
 const times=[0,.25,.5,.75].map(fraction=>fraction*period);
 const out=document.createElement('canvas');out.width=1200;out.height=650;const ctx=out.getContext('2d');
 ctx.fillStyle='#fffaf0';ctx.fillRect(0,0,out.width,out.height);ctx.fillStyle='#282c30';ctx.font='17px sans-serif';
 ctx.fillText(`${pose} / ${expression} / ${lighting} · four sampled times · ${sheetStudyTag}`,12,24);
 for(let row=0;row<4;row++)for(let column=0;column<8;column++){
  const sample=reviewRender(96,column*45,148,120,{pose,expression,lighting,time:times[row]});
  const x=column*150,y=50+row*150;ctx.drawImage(sample.canvas,x+1,y);
  ctx.fillStyle='#282c30';ctx.font='12px sans-serif';ctx.fillText(`${column*45}° · ${times[row].toFixed(3)}s`,x+8,y+137);
 }
 const link=$('download');link.href=out.toDataURL('image/png');link.download=`sailor-${sheetStudyTag}-${pose}-${expression}-${lighting}-four-phases-eight-views.png`;
 link.textContent=`Download ${pose} movement sheet · four sampled times / eight directions`;link.hidden=false;
}
$('captureMotion').onclick=saveMotionSheet;
function dispose(){if(dead)return;dead=true;cancelAnimationFrame(raf);observer.disconnect();model.dispose();floor.geometry.dispose();floorModes.flat.dispose();sceneryBank.dispose();wall.geometry.dispose();wall.material.dispose();grid.geometry.dispose();grid.material.dispose();renderer.dispose();renderer.forceContextLoss();}
addEventListener('pagehide',dispose);window.study={model,scene,renderer,get camera(){return camera;},setYaw,reset,reviewRender,dispose,stats:()=>({model:model.stats(),render:{...renderer.info.render},memory:{...renderer.info.memory}})};

function referenceView(head){document.getElementById('referenceClipRect').setAttribute('height',head?'1700':'2380');document.getElementById('referenceCrop').parentElement.classList.toggle('headCrop',head);document.getElementById('referenceCrop').setAttribute('viewBox',head?'430 850 2380 1700':'430 850 2380 2380');document.getElementById('referenceCrop').setAttribute('aria-label',head?'Unchanged original sailor, head crop':'Unchanged original sailor, character crop');document.getElementById('referenceHead').setAttribute('aria-pressed',String(head));document.getElementById('referenceCharacter').setAttribute('aria-pressed',String(!head));}document.getElementById('referenceHead').onclick=()=>referenceView(true);document.getElementById('referenceCharacter').onclick=()=>referenceView(false);
